mapper.select:
select min(id) as minId, max(id) as maxId, count(1) as count
from ods_user u
where u.dates = #{dates}

select min(id) as minId, max(id) as maxId, count(1) as count
from dwd_user_register
where dates = #{dates}

select dur.*, IFNULL(dus.network, 'Unknown') user_source
from dwd_user_register dur
         left join dim_user_source dus on (dur.user_id = dus.user_id)
where dur.dates = #{dates}
  and dur.id >= #{startId}
  and  dur.id <= #{endId}
